import{$,$$,status}from'./common.js';const rooms={lake:{name:'Lake House',rate:12000,max:2},forest:{name:'Forest Cabin',rate:15000,max:2},suite:{name:'Garden Suite',rate:19000,max:4}};const money=n=>'₹'+n.toLocaleString('en-IN');function localDate(d){return[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}const today=new Date(),tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);const end=new Date(today);end.setDate(today.getDate()+3);$('#checkin').min=localDate(today);$('#checkin').value=localDate(tomorrow);$('#checkout').value=localDate(end);
function calculation(){const room=rooms[$('#roomChoice').value],a=$('#checkin').value,b=$('#checkout').value;const start=Date.parse(a+'T00:00:00Z'),finish=Date.parse(b+'T00:00:00Z'),nights=(finish-start)/86400000;const next=new Date(start+86400000);if(Number.isFinite(start))$('#checkout').min=next.toISOString().slice(0,10);$$('[data-room]').forEach(x=>x.classList.toggle('active',x.dataset.room===$('#roomChoice').value));if(!a||!b||!Number.isInteger(nights)||nights<1||a<localDate(today)){throw Error('Choose a future arrival and a departure at least one day later.')}if(nights>30)throw Error('Choose a stay of 30 nights or fewer for this demo.');if(+$('#guests').value>room.max)throw Error(room.name+' accommodates up to '+room.max+' guests. Choose Garden Suite for more guests.');$('#stayNights').textContent=nights+' night'+(nights===1?'':'s');$('#stayPrice').textContent=money(room.rate*nights);return{room,nights,total:room.rate*nights,a,b}}
function update(){try{calculation();status('Explore the dates, rooms and guests to plan a sample stay.')}catch(e){$('#stayPrice').textContent='—';$('#stayNights').textContent='Review your stay';status(e.message,true)}}$$('[data-room]').forEach(b=>b.onclick=()=>{$('#roomChoice').value=b.dataset.room;update();if(!document.documentElement.classList.contains('embed'))$('#stay').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})});['roomChoice','checkin','checkout','guests'].forEach(id=>$('#'+id).oninput=update);$('#stayForm').onsubmit=e=>{e.preventDefault();try{const stay=calculation();status('Sample stay: '+stay.room.name+', '+stay.nights+' nights, '+money(stay.total)+'. No reservation was placed.')}catch(e){status(e.message,true)}};update();
